/* @lc app=leetcode id=2538 lang=kotlin */ class Solution { fun maxOutput(n: Int, edges: Array<IntArray>, price: IntArray): Long = edges.flatMap { (a, b) -> listOf(a to b, b to a) }.groupBy({ it.first }, { it.second }).let { g -> IntArray(n) { -1 }.also { it[0] = 0 }.let { par -> generateSequence(listOf(0)) { f -> f.flatMap { u -> g[u].orEmpty().filter { v -> par[v] == -1 }.onEach { v -> par[v] = u } }.takeIf { it.isNotEmpty() } }.flatten().toList().reversed().let { order -> LongArray(n).let { wl -> LongArray(n).let { wo -> order.fold(0L) { best, v -> g[v].orEmpty().filter { par[it] == v && it != 0 }.let { ch -> ch.fold(Triple(Long.MIN_VALUE / 4, Long.MIN_VALUE / 4, 0L)) { (bwl, bwo, cand), c -> Triple(maxOf(bwl, wl[c]), maxOf(bwo, wo[c]), maxOf(cand, price[v] + wo[c], wl[c], if (bwl > Long.MIN_VALUE / 4) price[v] + maxOf(bwl + wo[c], bwo + wl[c]) else 0L)) }.also { wl[v] = price[v] + (ch.maxOfOrNull { wl[it] } ?: 0L) }.also { wo[v] = if (ch.isEmpty()) 0L else price[v] + ch.maxOf { wo[it] } }.let { maxOf(best, it.third) } } } } } } } } }